  `TicketValidityEnd` datetime DEFAULT NULL,
  PRIMARY KEY (`EventItemTypeId`),
  KEY `EventIdRef1_idx` (`EventId`),
  CONSTRAINT `EventIdRef2` FOREIGN KEY (`EventId`) REFERENCES `events` (`EventId`)
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
